import pathlib
p = pathlib.Path('src/codegen_support/runtime/io/glob.rs')
t = p.read_text()
t = t.replace('''    for (php_bit, libc_bit, name) in glob_flag_translation(emitter) {
        emitter.instruction(&format!(\"orr x12, x11, #{libc_bit}\"));             // the flags this one would add''', '''    for (php_bit, libc_bit, name) in glob_flag_translation(emitter) {
        emitter.comment(&format!(\"php {name} -> this platform's libc bit\"));
        emitter.instruction(&format!(\"orr x12, x11, #{libc_bit}\"));             // the flags this one would add''')
t = t.replace('''        emitter.instruction(&format!(\"csel x11, x12, x11, ne\"));                // translate php's {name}''', '''        emitter.instruction(\"csel x11, x12, x11, ne\");                          // keep it only when php's caller set the bit''')
t = t.replace('''    for (php_bit, libc_bit, name) in glob_flag_translation(emitter) {
        emitter.instruction(\"mov r9, r8\");''', '''    for (php_bit, libc_bit, name) in glob_flag_translation(emitter) {
        emitter.comment(&format!(\"php {name} -> this platform's libc bit\"));
        emitter.instruction(\"mov r9, r8\");''')
t = t.replace('''        emitter.instruction(&format!(\"cmovnz r8, r9\"));                         // translate php's {name}''', '''        emitter.instruction(\"cmovnz r8, r9\");                                   // keep it only when php's caller set the bit''')
p.write_text(t)
print('translation loops name the flag in the emitted asm')
